const roles = {duelist:'Duelist',initiator:'Initiator',controller:'Controller',sentinel:'Sentinel'};
const labels = new Map(equipment.map(item=>[item.id,item.label]));
const heroLabels = new Map(agents.map(item=>[item.id,item.label]));
function node(tag, className, text) {
 const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;
}
function button(className,text){const el=node('button',className,text);el.type='button';return el;}
function stat(label,value){const el=node('div','armoryStat');el.append(node('span','',label),node('strong','',String(value)));return el;}

// The server remains the owner of equipped items. Clicking never marks an item as equipped.
export function mountArmory(root,{onSelect=()=>{},onHero=()=>{}}={}) {
 let category='all', selectedTab='weapons', inspected='vandal', detailKey='', inspectionPinned=false;
 const shell=node('div','armoryShell');
 const header=node('header','armoryHeader'), heading=node('div');
 heading.append(node('div','armoryEyebrow','OFFSET / FREE LOADOUT'),node('h2','','Armory'),node('p','','Choose a weapon to equip it. All equipment is free.'));
 const close=button('armoryClose','Close ×');close.id='closeArmory';close.setAttribute('aria-label','Close armory');header.append(heading,close);
 const banner=node('div','armoryLoadout');banner.setAttribute('aria-label','Current loadout');
 const bannerValues={};
 for(const [id,title,key] of [['primary','1 / Primary','1'],['sidearm','2 / Sidearm','2'],['melee','3 / Melee','3'],['hero','Agent','']]){
  const block=node('div','armoryLoadoutSlot');const value=node('strong','','—');block.append(node('span','',title),value);bannerValues[id]={block,value,key};banner.append(block);
 }
 const tabs=node('div','armoryTabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Equipment categories');
 const weaponTab=button('armoryTab',`Weapons ${equipment.length}`), heroTab=button('armoryTab',`Agents ${agents.length}`), skinTab=button('armoryTab',`Appearance ${variants.length}`);
 weaponTab.id='armoryTabWeapons';heroTab.id='armoryTabAgents';skinTab.id='armoryTabSkins';
 const weaponPanel=node('div','armoryPanel'), heroPanel=node('div','armoryPanel'), skinPanel=node('div','armoryPanel');weaponPanel.id='armoryWeaponsPanel';heroPanel.id='armoryAgentsPanel';skinPanel.id='armorySkinsPanel';
 const tabEntries=[[weaponTab,weaponPanel,'weapons'],[heroTab,heroPanel,'agents'],[skinTab,skinPanel,'skins']];
 for(const [tab,panel] of tabEntries){tab.setAttribute('role','tab');tab.setAttribute('aria-controls',panel.id);panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);}
 tabs.append(weaponTab,heroTab,skinTab);
 const stateNote=node('p','armoryStateNote');
 const filter=node('div','armoryFilters');filter.setAttribute('aria-label','Weapon category');const filterButtons=new Map();
 for(const [id,label] of categories){const b=button('armoryFilter',label);b.onclick=()=>{category=id;refreshFilters();};filterButtons.set(id,b);filter.append(b);}
 const weaponGrid=node('div','armoryWeaponGrid'), heroGrid=node('div','armoryHeroGrid');
 const categoryTargets=new Map();
 for(const groups of [['sidearm','melee'],['smg','shotgun'],['rifle'],['sniper','machine']]){
  const column=node('div','armoryCategoryColumn');
  for(const id of groups){const group=node('section','armoryCategoryGroup');group.dataset.category=id;group.append(node('h3','armoryCategoryHeading',categories.find(c=>c[0]===id)[1]));categoryTargets.set(id,group);column.append(group);}
  weaponGrid.append(column);
 }
 const weaponCards=new Map(), heroCards=new Map();
 const readyCount=equipment.filter(item=>item.ready).length;
 const weaponNote=node('p','armoryCatalogNote',`${equipment.length-1} firearms + melee · ${readyCount} selectable items · Hover to inspect stats`);
 for(const item of equipment){
  const card=button('armoryWeaponCard','');card.dataset.equipment=item.id;
  const top=node('div','armoryCardTop');top.append(node('span','armoryCardCategory',categories.find(c=>c[0]===item.category)?.[1]||item.category),node('span','armoryReady',item.ready?'Available':'Coming soon'));
  const icon=node('span','armoryWeaponIcon');icon.innerHTML=weaponIcons[item.id]||'';
  card.append(icon,node('strong','armoryWeaponName',item.label),node('span','armoryCardAction',item.ready?'Equip':'Coming soon'));
  card.setAttribute('aria-label',`${item.label}, ${item.ready?'Equip':'Coming soon, Not selectable yet'}`);
  card.onclick=()=>{inspectionPinned=true;inspected=item.id;refreshDetail();status(`Confirming ${item.label}…`);onSelect(item.id);};
  const preview=()=>{inspectionPinned=true;inspected=item.id;refreshDetail();};card.onfocus=preview;card.onpointerenter=preview;weaponCards.set(item.id,{card,item});categoryTargets.get(item.category).append(card);
 }
 const detail=node('aside','armoryDetail');detail.setAttribute('aria-label','Weapon stats and appearance');
 const catalog=node('section','armoryCatalog');catalog.append(weaponNote,filter,weaponGrid);
 const loadoutLabel=node('h3','armoryCategoryHeading','Current loadout');banner.prepend(loadoutLabel);
 weaponPanel.append(banner,catalog,detail);
 const heroNote=node('p','armoryCatalogNote',`${agents.length} agent assets. Jett is playable; other agents require model, rig and animation verification. Each agent will retain its original arms and animations.`);
 for(const item of agents){
  const card=button('armoryHeroCard','');card.dataset.agent=item.id;
  card.append(node('span','armoryHeroRole',roles[String(item.role).toLowerCase()]||item.role),node('strong','',item.label),node('span','armoryReady',item.ready?'Available':'Coming soon'));
  card.setAttribute('aria-label',`${item.label}, ${item.ready?'Select agent':'Coming soon, Not selectable yet'}`);
  card.onclick=()=>{status(`Confirming ${item.label}…`);onHero(item.id);};heroCards.set(item.id,{card,item});heroGrid.append(card);
 }
 heroPanel.append(heroNote,heroGrid);
 const skinNote=node('p','armoryCatalogNote',`${variants.length} appearance assets. Default skins are available. Other variants require model, attachment and animation verification before selection.`);
 const skinGrid=node('div','armorySkinGrid');
 for(const skin of variants){const card=node('div','armoryVariantCard');card.setAttribute('aria-disabled','true');card.append(node('span','armoryHeroRole',labels.get(skin.weapon)||skin.weapon),node('strong','',skin.label),node('span','armoryReady',skin.ready?'Integrated · Selection is not available yet':'Coming soon'));skinGrid.append(card);}
 const defaults=node('div','armoryDefaultRoster');defaults.append(node('p','armoryCatalogNote','Default appearance'));
 const defaultGrid=node('div','armorySkinGrid');
 for(const item of equipment){const card=node('div','armoryVariantCard');card.setAttribute('aria-disabled','true');card.append(node('span','armoryHeroRole',item.label),node('strong','','Default appearance'),node('span','armoryReady',item.ready?'Available now':'Available with the weapon'));defaultGrid.append(card);}
 defaults.append(defaultGrid);skinPanel.append(skinNote,skinGrid,defaults);
 const message=node('p','armoryStatus');message.setAttribute('role','status');message.setAttribute('aria-live','polite');
 const footer=node('footer','armoryFooter','B close · Esc settings · WASD move · 1 / 2 / 3 or scroll: switch weapons · All equipment is free');
 shell.append(header,tabs,stateNote,weaponPanel,heroPanel,skinPanel,message,footer);root.replaceChildren(shell);
 function status(text,isError=false){message.textContent=text;message.classList.toggle('isError',isError);}
 function selectTab(id){selectedTab=id;for(const [tab,panel,name] of tabEntries){tab.setAttribute('aria-selected',String(id===name));tab.tabIndex=id===name?0:-1;panel.hidden=id!==name;}}
 for(const [tab,,name]of tabEntries)tab.onclick=()=>selectTab(name);
 tabs.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const active=tabEntries.findIndex(entry=>entry[2]===selectedTab),next=e.key==='Home'?0:e.key==='End'?tabEntries.length-1:(active+(e.key==='ArrowLeft'?-1:1)+tabEntries.length)%tabEntries.length;selectTab(tabEntries[next][2]);tabEntries[next][0].focus();};
 function refreshFilters(){for(const [id,b]of filterButtons)b.setAttribute('aria-pressed',String(category===id));for(const{card,item}of weaponCards.values())card.hidden=category!=='all'&&item.category!==category;}
 function refreshDetail(){
  if(detailKey===inspected)return;detailKey=inspected;const item=equipment.find(item=>item.id===inspected), spec=WEAPONS[inspected];if(!item)return;
  const title=node('div','armoryDetailTitle');title.append(node('strong','',item.label),node('span','',categories.find(c=>c[0]===item.category)?.[1]+' / Default appearance'));
  const detailIcon=node('div','armoryDetailIcon');detailIcon.innerHTML=weaponIcons[item.id]||'';
  const stats=node('div','armoryStats');
  if(spec){
   const wiki=WEAPON_WIKI[inspected];
   if(spec.capacity>0){
    stats.append(stat('Magazine',spec.capacity),stat('Fire rate',`${(1000/spec.interval).toFixed(2)} / s`),stat('Reload',`${spec.reload/1000} s`),stat('Run speed',`${spec.runSpeed} m/s`),stat('Equip time',`${spec.equip/1000} s`),stat('Fire mode',spec.automatic?'Auto':'Semi'));
    for(const band of weaponDamageBands(inspected))stats.append(stat(`${band.from}–${band.to}m · ${spec.pellets>1?"Per pellet · ":""}Head / Body / Leg`,`${band.head} / ${band.body} / ${band.leg}`));
    stats.append(stat('Wiki reserve / Training',`${wiki.reserve} / ∞`),stat('Wiki Wall penetration',wiki.penetration),stat('Wiki Fast / Instant equip',`${wiki.equipFast/1000} / ${wiki.equipInstant/1000} s`));
    if(spec.pellets)stats.append(stat('Pellets per shot',spec.pellets));if(spec.secondary)stats.append(stat('Secondary fire',spec.secondary.kind==='airburst'?'7.5m Airburst / 5 Pellets':'3 rounds / Consumes 3 Bullets'));if(spec.ads?.burst)stats.append(stat('ADS Burst',spec.ads.burst.count+' rounds'));if(spec.reloadPerRound)stats.append(stat('Per-round reload',spec.reloadPerRound/1000+' s / round'));if(spec.ads)stats.append(stat('ADS Zoom / Fire rate',`${spec.ads.zoom}× / ${(1000/spec.ads.interval).toFixed(3)} / s`),stat('ADS Movement speed',`${spec.ads.moveSpeed} m/s`));
    if(wiki.silenced)stats.append(stat('Weapon features','Silenced'));
   }else stats.append(stat('Front · Light / Heavy',`${spec.body} / ${spec.secondary.body}`),stat('Back · Light / Heavy',`${spec.back} / ${spec.secondary.back}`),stat('Run speed',`${spec.runSpeed} m/s`),stat('Knife equip time',`${spec.equip/1000} s`));
  }
  const skins=node('div','armorySkins');skins.append(node('span','armorySkinDefault','Default appearance · Available'));
  for(const skin of variants.filter(v=>v.weapon===inspected))skins.append(node('span','armorySkinPending',`${skin.label} · ${skin.ready?'Integrated':'Coming soon'}`));
  const notes=node('p','armoryCatalogNote',!spec?'This equipment is not available yet. Runtime stats still need verification.':spec.capacity>0?'Damage is shown before armor and wall penetration. Training uses unlimited reserve ammunition. Penetration ratings and fast equip times are Wiki references; these systems are not implemented.':'Knife backstabs deal double damage. Light and heavy attack ranges follow the current training rules.');
  const source=node('a','armoryCatalogNote','View Wiki stats');source.href=WEAPON_WIKI[inspected]?.url||'https://valorant.fandom.com/wiki/Weapons';source.target='_blank';source.rel='noopener noreferrer';
  detail.replaceChildren(title,detailIcon,stats,notes,source,skins);
 }
 function update(player,phase){
  if(!player)status('');
  const loadout=player?.loadout||{}, blocked=!player||player.hp<=0||['paused','finished'].includes(phase);
  stateNote.textContent=!player?'Join a room to select equipment.':player.hp<=0?'Wait until you respawn to change equipment.':phase==='paused'?'Match paused. Resume to change equipment.':phase==='finished'?'Match ended. Change equipment when the next round starts.':'Change equipment during training or a match. Ammunition and firing cooldowns are preserved.';
  for(const[id,{block,value}]of Object.entries(bannerValues)){const selected=id==='hero'?heroLabels.get(loadout.hero||'jett'):labels.get(loadout[id]||(id==='primary'?'vandal':id==='sidearm'?'ghost':'knife'));value.textContent=player?(selected||'—'):'—';block.classList.toggle('isActive',!!player&&id!=='hero'&&loadout[id]===player.weapon);}
  for(const{card,item}of weaponCards.values()){card.disabled=blocked||!item.ready;const selected=Object.values(loadout).includes(item.id);card.setAttribute('aria-pressed',String(selected));card.classList.toggle('isHeld',player?.weapon===item.id);}
  for(const{card,item}of heroCards.values()){card.disabled=blocked||!item.ready;card.setAttribute('aria-pressed',String((loadout.hero||'jett')===item.id&&!!player));}
  if(!inspectionPinned&&player?.weapon&&WEAPONS[player.weapon])inspected=player.weapon;
  refreshDetail();
 }
 selectTab('weapons');refreshFilters();refreshDetail();update(null,'');
 return {update,status};
}
